//! The console's HTML: the shell page and the server-rendered preview.
//!
//! The markup is generated by **maud**, a compile-time HTML generator: the
//! page is Rust code (no template files, no runtime parser, no runtime file
//! dependency) and maud **escapes every interpolated value**, so untrusted
//! cell content can never become markup. The one construct maud does *not*
//! escape is `pre_escaped!`, which this module never uses.

use axum::response::IntoResponse;
use maud::{DOCTYPE, Markup, html};

use crate::api::ColumnInfo;
use crate::server::Shared;

/// One previewed cell: its text, whether it is NULL, and whether it was
/// truncated.
pub type Cell = (String, bool, bool);

/// The server-rendered preview page.
pub struct PreviewPage {
    /// The database the rows come from.
    pub db: String,
    /// The schema the rows come from.
    pub schema: String,
    /// The relation the rows come from.
    pub table: String,
    /// The 1-based page number.
    pub page: u64,
    /// The effective page size.
    pub page_size: usize,
    /// The exact total row count.
    pub total_rows: u64,
    /// The number of pages.
    pub total_pages: u64,
    /// The relation's columns.
    pub columns: Vec<ColumnInfo>,
    /// The page's rows.
    pub rows: Vec<Vec<Cell>>,
}

/// The favicon, inline (the CSP allows `data:` images): `brand/icon/favicon.svg`,
/// regenerated by `brand/make-brand.py`. The namespace's colon is encoded too,
/// so the shell holds no `http://` at all (`the_shell_page_is_self_hosted`).
const FAVICON: &str = "data:image/svg+xml,%3Csvg xmlns='http%3A//www.w3.org/2000/svg' viewBox='0 0 32 32'%3E\
%3Crect width='32' height='32' rx='7' fill='%23241F1C'/%3E%3Cg transform='scale(0.5)'%3E\
%3Cpath fill='%23F7F1E8' d='M9 14a6 6 0 0 1 12 0v36a6 6 0 0 1-12 0z'/%3E\
%3Ccircle cx='39.5' cy='23.5' r='15.5' fill='%23D6336C'/%3E%3C/g%3E%3C/svg%3E";

/// The console shell: the stylesheet and the app's boot module. The page
/// carries no data; the app (wave 121) logs in and fetches everything.
pub fn shell(_shared: &Shared) -> Markup {
    html! {
        (DOCTYPE)
        html lang="en" {
            head {
                meta charset="utf-8";
                meta name="viewport" content="width=device-width, initial-scale=1";
                title { "pinkdb warehouse console" }
                link rel="icon" type="image/svg+xml" href=(FAVICON);
                link rel="stylesheet" href="/assets/console.css";
                script type="module" src="/assets/boot.js" {}
            }
            body {
                noscript {
                    p class="noscript" {
                        "The console needs JavaScript and WebAssembly. A server-rendered, \
                         read-only row preview is at "
                        code { "/preview?db=<database>&table=<table>" }
                        "."
                    }
                }
            }
        }
    }
}

/// The console shell as an HTTP response.
pub fn shell_response(shared: &Shared) -> axum::response::Response {
    axum::response::Html(shell(shared).into_string()).into_response()
}

/// The server-rendered preview page as an HTTP response.
pub fn preview_response(page: &PreviewPage) -> axum::response::Response {
    axum::response::Html(preview_page(page).into_string()).into_response()
}

/// The server-rendered preview page.
pub fn preview_page(page: &PreviewPage) -> Markup {
    html! {
        (DOCTYPE)
        html lang="en" {
            head {
                meta charset="utf-8";
                meta name="viewport" content="width=device-width, initial-scale=1";
                title { "pinkdb — " (page.db) "." (page.schema) "." (page.table) }
                link rel="icon" type="image/svg+xml" href=(FAVICON);
                link rel="stylesheet" href="/assets/console.css";
            }
            body class="preview-page" {
                header class="topbar" {
                    span class="brand__mark" aria-hidden="true" { "p" }
                    span class="brand__name" { "pinkdb " span class="brand__sub" { "Warehouse" } }
                    span class="topbar__sep" {}
                    span class="crumbs" {
                        (page.db) span class="crumbs__sep" { "›" } (page.schema) span class="crumbs__sep" { "›" } span class="mono" { (page.table) }
                    }
                    span class="spacer" {}
                    span class="badge badge--warning" { "Read-only preview" }
                }
                main class="preview" {
                    div class="results__bar preview__summary" {
                        strong { (page.total_rows) } " rows · page " (page.page) " of " (page.total_pages.max(1))
                    }
                    div class="grid" {
                        table {
                            thead {
                                tr {
                                    th class="grid__rn" { "#" }
                                    @for column in &page.columns {
                                        th {
                                            span class="grid__name" { (column.name) }
                                            span class="grid__type" { (column.dtype) }
                                        }
                                    }
                                    th class="col-fill" {}
                                }
                            }
                            tbody {
                                @for (i, row) in page.rows.iter().enumerate() {
                                    tr {
                                        td class="grid__rn" { (page.page.saturating_sub(1) * page.page_size as u64 + i as u64 + 1) }
                                        @for (text, is_null, truncated) in row {
                                            @if *is_null {
                                                td class="is-null" { "NULL" }
                                            } @else if *truncated {
                                                td class="truncated" title=(text) { (text) }
                                            } @else {
                                                td { (text) }
                                            }
                                        }
                                        td {}
                                    }
                                }
                            }
                        }
                    }
                    @if page.rows.is_empty() {
                        p class="empty" { "No rows on this page." }
                    }
                    nav class="pager" {
                        @if page.page > 1 {
                            a class="btn btn--sm" href=(page_link(page, page.page - 1)) { "Previous" }
                        }
                        span { "Page " (page.page) " of " (page.total_pages.max(1)) }
                        @if page.page < page.total_pages {
                            a class="btn btn--sm" href=(page_link(page, page.page + 1)) { "Next" }
                        }
                    }
                }
            }
        }
    }
}

/// The link to another page of the same preview.
fn page_link(page: &PreviewPage, target: u64) -> String {
    format!(
        "/preview?db={}&schema={}&table={}&page={}&page_size={}",
        url_encode(&page.db),
        url_encode(&page.schema),
        url_encode(&page.table),
        target,
        page.page_size
    )
}

/// Percent-encode a query-parameter value.
fn url_encode(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.as_bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(*byte as char);
            }
            other => out.push_str(&format!("%{other:02X}")),
        }
    }
    out
}
